import {escapeHTML as e} from '../../shared/primitives.js';
import {avatar,icon,pageHeading,empty} from '../../shared/ui.js';
const locationName=(c,id)=>c.locations.find(l=>l.id===id)?.name||'Local desconhecido';
const button=(action,label,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${icon('plus')}${label}</button>`;
import {renderMap} from './interactions.js';
import {mapRegion,mapCharacters,regionMembers} from './domain.js';
export function inspector(c,id,mapId) {
 const available=mapId?mapCharacters(c,mapId):c.characters;
 const ch=available.find(v=>v.id===id)||available[0];
 if(!ch)return `<aside class="inspector">${empty('Nenhum personagem aqui','Adicione uma ficha e escolha esta região.','<button data-action="new-character">Criar personagem</button>')}</aside>`;
 return `<aside class="inspector"><div class="inspector-top"><span class="eyebrow">EM FOCO</span><button class="text-button" data-edit-character="${e(ch.id)}">Editar ↗</button></div><button class="portrait-button" data-open-character="${e(ch.id)}" aria-label="Ampliar ficha de ${e(ch.name)}">${avatar(ch,'portrait')}<div class="portrait-shade"></div><div class="portrait-caption"><small>${e(ch.role)}</small><h2>${e(ch.name)}</h2></div></button><div class="inspector-body"><div class="location-line">${icon('pin')} ${e(locationName(c,ch.locationId))}</div><div class="rank-row"><span>RANK</span><strong>${e(ch.rank)}</strong></div><h3>O que sabemos</h3><p class="summary-preview">${e(ch.summary)}</p><h3>Vínculos</h3><p>${e(ch.relations)}</p><button class="wide" data-open-character="${e(ch.id)}">Abrir ficha completa ${icon('arrow')}</button></div></aside>`;
}
export function atlas(c,ui) {
 const current=mapRegion(c,ui.mapId),isScene=current?.kind==='subregion';
 return `${pageHeading(current?(isScene?'EXPLORANDO O LOCAL':'EXPLORANDO A REGIÃO'):'A CAMPANHA EM MOVIMENTO',current?current.name:'Atlas do mundo',current?'A história se aproxima. Explore os lugares e os personagens presentes.':'Aponte uma região para ler o resumo. Clique para entrar no seu mapa.',button('new-character','Novo personagem',true))}
 <div class="campaign-strip"><div>${icon('moon')} <strong>${e(c.name)}</strong><span class="muted">${e(c.subtitle)}</span></div><span class="date-pill">${e(c.day)}</span></div>
 <div class="atlas-layout"><div class="atlas-left"><section class="atlas-panel">${renderMap(c,ui.mapId,ui.selectedId,ui)}</section>${regionalContext(c,ui.mapId)}<div class="stats-grid"><a href="#personagens"><span>${icon('people')} PERSONAGENS</span><strong>${c.characters.length.toString().padStart(2,'0')}</strong><small>Vozes deste universo</small></a><a href="#capitulos"><span>${icon('book')} CAPÍTULOS</span><strong>${c.chapters.filter(v=>v.status==='Concluído').length.toString().padStart(2,'0')}<em> / ${c.chapters.length.toString().padStart(2,'0')}</em></strong><small>Concluídos / no arquivo</small></a><a href="#tramas"><span>${icon('spark')} TRAMAS ABERTAS</span><strong>${c.threads.filter(v=>v.status!=='Resolvido').length.toString().padStart(2,'0')}</strong><small>Histórias por desvendar</small></a></div></div>${inspector(c,ui.selectedId,ui.mapId)}</div>
 <div class="below-grid"><section class="panel next-chapter"><div class="eyebrow">NA PRÓXIMA PÁGINA</div><h2>${e(c.chapters.find(v=>v.status==='Rascunho')?.title||'O próximo capítulo é seu')}</h2><p>${e(c.chapters.find(v=>v.status==='Rascunho')?.body.slice(0,170)||'Guarde ideias, encontros e acontecimentos para continuar sua campanha.')}${c.chapters.some(v=>v.status==='Rascunho')?'…':''}</p><a href="#capitulos">Continuar a crônica ${icon('arrow')}</a></section><section class="panel"><div class="section-line"><h2>Nos arquivos do reino</h2><span class="muted">REGISTROS RECENTES</span></div>${(c.history||[{description:'Compêndio organizado · Dia 26 da Lua Pálida',date:c.updatedAt}]).slice(-3).reverse().map(h=>`<div class="history-row"><span class="history-dot"></span><div>${e(h.description)}<small>${new Date(h.date).toLocaleString('pt-BR')}</small></div></div>`).join('')}</section></div>`;
}
function regionalContext(c,mapId) {
 const region=mapRegion(c,mapId),children=c.regions.filter(r=>r.worldMapId===mapId);
 let content='';
 if(region){const members=regionMembers(c,region.id);content=`<section class="panel active-region"><div class="section-line"><div><div class="eyebrow">${region.kind==='subregion'?'CONTEXTO DO LOCAL':'ESTADO DA REGIÃO'}</div><h2>${e(region.name)}</h2></div><button class="text-button" data-edit-region="${e(region.id)}">Editar resumo e contorno ↗</button></div><p>${e(region.summary)}</p><div class="section-line"><h3>${members.length} ${members.length===1?'personagem presente':'personagens presentes'}</h3><button class="text-button" data-filter-region="${e(region.id)}">Ver fichas deste local ↗</button></div><div class="region-members">${members.map(ch=>`<button class="character-chip" data-open-character="${e(ch.id)}">${avatar(ch)}${e(ch.name)}</button>`).join('')||'<p class="muted">Nenhum personagem registrado neste local.</p>'}</div></section>`;}
 if(children.length)content+=`<section class="subregion-gallery"><div class="section-line"><div><div class="eyebrow">${region?'APROXIME A HISTÓRIA':'EXPLORE O REINO'}</div><h2>${region?'Sub-regiões e locais ilustrados':'Regiões do mapa'}</h2></div><span class="muted">${children.length} ${children.length===1?'local disponível':'locais disponíveis'}</span></div><div class="region-strip ${region?'scene-grid':''}" aria-label="${region?'Sub-regiões disponíveis':'Acesso aos mapas regionais'}">${children.map(r=>`<button data-region="${e(r.id)}" class="region-tile"><img src="${e(c.maps.find(m=>m.id===r.mapId).image)}" alt="${e(r.name)}" loading="lazy"><span><strong>${e(r.name)}</strong><small>${regionMembers(c,r.id).length} personagens · Explorar ↗</small></span></button>`).join('')}</div></section>`;
 else if(region&&region.kind!=='subregion')content+=`<section class="panel scenes-pending"><h3>As próximas imagens estão a caminho</h3><p class="muted">Esta região continua disponível. Seus locais ilustrados aparecerão aqui quando forem adicionados.</p><button data-action="new-subregion">Conectar uma sub-região</button></section>`;
 return content;
}
